#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1000000007;

struct Number {
    int val;

    Number(long long v = 0) {
        if (v < 0) v %= MOD, v += MOD;
        if (v >= MOD) v %= MOD;
        val = v;
    }

    static int inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    Number& operator+=(const Number &other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    Number& operator-=(const Number &other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    Number& operator*=(const Number &other) {
        val = fast_mod((uint64_t) val * other.val);
        return *this;
    }

    Number& operator/=(const Number &other) {
        return *this *= Number(inverse(other.val));
    }

    friend Number operator+(const Number &a, const Number &b) { return Number(a) += b; }
    friend Number operator-(const Number &a, const Number &b) { return Number(a) -= b; }
    friend Number operator*(const Number &a, const Number &b) { return Number(a) *= b; }
    friend Number operator/(const Number &a, const Number &b) { return Number(a) /= b; }

    Number& operator++() {
        val = val == MOD - 1 ? 0 : val + 1;
        return *this;
    }

    Number& operator--() {
        val = val == 0 ? MOD - 1 : val - 1;
        return *this;
    }

    Number operator++(int) { Number before = *this; ++*this; return before; }
    Number operator--(int) { Number before = *this; --*this; return before; }

    Number operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const Number &other) const { return val == other.val; }
    bool operator!=(const Number &other) const { return val != other.val; }

    Number inv() const {
        return Number(inverse(val));
    }

    Number pow(long long p) const {
        assert(p >= 0);
        Number base = *this, result = 1;
        while (p > 0) {
            if (p & 1)
                result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_N = 7;

int N;
Number prob[MAX_N][MAX_N];

int main() {
    cin >> N;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p;
            cin >> p;
            prob[i][j] = Number(p) / Number(100);
        }

    map<vector<bool>, Number> state_map;
    vector<bool> init_mask(1 << N, false);
    init_mask[0] = true;
    state_map[init_mask] = 1;
    vector<bool> temp_mask;

    for (int left_idx = 0; left_idx < N; left_idx++) {
        map<vector<bool>, Number> new_state_map;
        for (int mask_curr = 0; mask_curr < (1 << N); mask_curr++) {
            Number product = 1;
            for (int right_idx = 0; right_idx < N; right_idx++)
                product *= (mask_curr >> right_idx & 1) ? prob[left_idx][right_idx] : Number(1) - prob[left_idx][right_idx];

            for (auto &entry : state_map) {
                const vector<bool> &possible_mask = entry.first;
                Number prob_value = entry.second;
                temp_mask.assign(1 << N, false);
                for (int m = 0; m < (1 << N); m++)
                    if (possible_mask[m])
                        for (int i = 0; i < N; i++)
                            if ((mask_curr >> i & 1) != 0 && (m >> i & 1) == 0)
                                temp_mask[m | (1 << i)] = true;

                new_state_map[temp_mask] += prob_value * product;
            }
        }
        state_map = new_state_map;
    }

    Number total = 0;
    for (auto &p : state_map)
        if (p.first[(1 << N) - 1])
            total += p.second;

    cout << (int) total << '\n';
}
